(1826809, 251245, 8455, '<td valign="top">I like porto, and the distorted bottle is really clear and has an interesting shape, but perhaps a colour other than orange/yellow could have been chosen for the backgroud?  It''s so bold, it almost overpowers.<br/>nitpick:  way off to the left by the border there seems to be a little extra line (missed when cloning out??)</td>', 'I like porto, and the distorted bottle is really clear and has an interesting shape, but perhaps a colour other than orange/yellow could have been chosen for the backgroud?  It''s so bold, it almost overpowers.nitpick:  way off to the left by the border there seems to be a little extra line (missed when cloning out??)', '2005-10-31 11:04:12.000000', NULL, 1),
(1826811, 250775, 43031, '<td valign="top">wow, a selctive desaturation pic that I actually like ;o)</td>', 'wow, a selctive desaturation pic that I actually like ;o)', '2005-10-31 11:05:28.000000', NULL, 1),
(1826815, 251010, 8455, '<td valign="top">Maybe a little silly, but why would the bottle have a cap on if there is a cap to the side?<br/> <br/>The image is well composed, but it might be nice to have seen the edges of the bottle (even really faintly), though I suppose that was for the ''transparency'' part of the challenge... (-:</td>', 'Maybe a little silly, but why would the bottle have a cap on if there is a cap to the side? The image is well composed, but it might be nice to have seen the edges of the bottle (even really faintly), though I suppose that was for the ''transparency'' part of the challenge... (-:', '2005-10-31 11:08:15.000000', NULL, 1),
(1826869, 250949, 42392, '<td valign="top">great picture and title=10</td>', 'great picture and title=10', '2005-10-31 11:28:00.000000', NULL, 1),
(1826907, 251414, 42392, '<td valign="top">had to look at this 3 times and more-great set up beautiful colors i would loved to critique this one more but i do not have the experience to do so-besides there is nothing wrong to me with this picture.</td>', 'had to look at this 3 times and more-great set up beautiful colors i would loved to critique this one more but i do not have the experience to do so-besides there is nothing wrong to me with this picture.', '2005-10-31 11:43:01.000000', NULL, 1),
(1826924, 251039, 40386, '<td valign="top">This really gets you thinking, how did u do that LOL. Never thought about looking through the lens backwards, gotta try it!!  Great shot!</td>', 'This really gets you thinking, how did u do that LOL. Never thought about looking through the lens backwards, gotta try it!!  Great shot!', '2005-10-31 11:52:31.000000', NULL, 1),
(1826931, 250109, 32321, '<td valign="top">Nice take on transperancy</td>', 'Nice take on transperancy', '2005-10-31 11:55:34.000000', NULL, 1),
(1826939, 251453, 36299, '<td valign="top">Very nicely done.  A none reflective surface would of worked well here to clean up the reflection. 9</td>', 'Very nicely done.  A none reflective surface would of worked well here to clean up the reflection. 9', '2005-10-31 11:59:04.000000', NULL, 1),
(1826943, 251531, 40386, '<td valign="top">This would have fared much better in the reflection without mirrors challenge, I dont see it as transparency, maybe I am missing something.  Great shot nonetheless.</td>', 'This would have fared much better in the reflection without mirrors challenge, I dont see it as transparency, maybe I am missing something.  Great shot nonetheless.', '2005-10-31 11:59:29.000000', NULL, 1),
(1826945, 250940, 36299, '<td valign="top">Awesome.  I love this......  A little mre contrast would of worked for me. 9</td>', 'Awesome.  I love this......  A little mre contrast would of worked for me. 9', '2005-10-31 11:59:33.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1826947, 251280, 36299, '<td valign="top">This is well done.  Nice work.</td>', 'This is well done.  Nice work.', '2005-10-31 12:00:12.000000', NULL, 1),
(1826950, 251388, 46651, '<td valign="top">It took me a while to figure out where the transparency lies in this image but now that I see it I have to say what a powerful interpretation of this challenge. The dark and almost "armageddon-like" message your image portrays is amazing. I think this will not be favored by most people on this site which is unfortunate. I like seeing images like this. It stirs the imagination and makes people think. Great job. If I could vote, I would have given this a 10! Great job!</td>', 'It took me a while to figure out where the transparency lies in this image but now that I see it I have to say what a powerful interpretation of this challenge. The dark and almost "armageddon-like" message your image portrays is amazing. I think this will not be favored by most people on this site which is unfortunate. I like seeing images like this. It stirs the imagination and makes people think. Great job. If I could vote, I would have given this a 10! Great job!', '2005-10-31 12:00:17.000000', NULL, 1),
(1826954, 248820, 36299, '<td valign="top">Neatr idea, I would of shifted the lens more to the left so only the eye could be seen in the filter.</td>', 'Neatr idea, I would of shifted the lens more to the left so only the eye could be seen in the filter.', '2005-10-31 12:01:31.000000', NULL, 1),
(1826956, 249432, 40386, '<td valign="top">Nice ... the highlight (softbox?) in her eye is a bit distracting.  Cool idea, good luck.</td>', 'Nice ... the highlight (softbox?) in her eye is a bit distracting.  Cool idea, good luck.', '2005-10-31 12:01:56.000000', NULL, 1),
(1826964, 250940, 40386, '<td valign="top">LOL Gret shot, it is a tad bit too bright (wishy washy?) tho and would be better with a bit more contrast and les brightness, make it pop more.  Good luck!</td>', 'LOL Gret shot, it is a tad bit too bright (wishy washy?) tho and would be better with a bit more contrast and les brightness, make it pop more.  Good luck!', '2005-10-31 12:05:29.000000', NULL, 1),
(1826972, 251353, 46586, '<td valign="top">I think I didn''t get it as I don''t see what is transparent there...sorry author</td>', 'I think I didn''t get it as I don''t see what is transparent there...sorry author', '2005-10-31 12:11:59.000000', NULL, 1),
(1826973, 251438, 40386, '<td valign="top">Well executed, great idea, Love this shot.</td>', 'Well executed, great idea, Love this shot.', '2005-10-31 12:12:58.000000', NULL, 1),
(1826975, 251557, 46586, '<td valign="top">I think this picture is really hard to read...</td>', 'I think this picture is really hard to read...', '2005-10-31 12:13:56.000000', NULL, 1),
(1826978, 251126, 32321, '<td valign="top">Excellent idea! Too bad the lens wasn''t in better focus. (Or is that before the lens is in!)  :-)</td>', 'Excellent idea! Too bad the lens wasn''t in better focus. (Or is that before the lens is in!)  :-)', '2005-10-31 12:16:02.000000', NULL, 1),
(1826979, 250002, 46586, '<td valign="top">Great balance and nice idea.</td>', 'Great balance and nice idea.', '2005-10-31 12:16:24.000000', NULL, 1),
(1826992, 251374, 46586, '<td valign="top">I love the idea, but imho the realisation is too gross...</td>', 'I love the idea, but imho the realisation is too gross...', '2005-10-31 12:23:27.000000', NULL, 1),
(1826993, 249329, 26464, '<td valign="top">background elements are showing and a bit distracting<br/></td>', 'background elements are showing and a bit distracting', '2005-10-31 12:23:57.000000', NULL, 1),
(1826996, 249920, 46586, '<td valign="top">I don''t know how it''s possible but  I love it.</td>', 'I don''t know how it''s possible but  I love it.', '2005-10-31 12:27:49.000000', NULL, 1),
(1827005, 250662, 43115, '<td valign="top">For me this does not meet the challenge.  Yes, windows are transparent, but in this case the viewer is not looking through them, but instead there is a reflection in them.  Better for the "reflections without mirrors" challenge than this one.  However, it is a very nice picture (i love the blue and the brown/orange), so that saves you from a ''1''.</td>', 'For me this does not meet the challenge.  Yes, windows are transparent, but in this case the viewer is not looking through them, but instead there is a reflection in them.  Better for the "reflections without mirrors" challenge than this one.  However, it is a very nice picture (i love the blue and the brown/orange), so that saves you from a ''1''.', '2005-10-31 12:36:41.000000', NULL, 1),
(1827024, 251268, 43400, '<td valign="top">Cool nostalgic image--great in sepia tone</td>', 'Cool nostalgic image--great in sepia tone', '2005-10-31 12:49:19.000000', NULL, 1),
(1827027, 248870, 43400, '<td valign="top">Clear graphic-like image---I like it</td>', 'Clear graphic-like image---I like it', '2005-10-31 12:50:52.000000', NULL, 1),
(1827029, 251453, 43400, '<td valign="top">Great colors and transparencies and composition and reflection and I like it-9</td>', 'Great colors and transparencies and composition and reflection and I like it-9', '2005-10-31 12:52:49.000000', NULL, 1),
(1827032, 250434, 43400, '<td valign="top">Cool pastel-painterly image</td>', 'Cool pastel-painterly image', '2005-10-31 12:53:51.000000', NULL, 1),
(1827039, 251475, 43400, '<td valign="top">I like the message here and great composition too. The orange-like hues I think is a bit strong--I would have gone a little cooler and not as intense and also more contrast could boost this up. Good imagery.</td>', 'I like the message here and great composition too. The orange-like hues I think is a bit strong--I would have gone a little cooler and not as intense and also more contrast could boost this up. Good imagery.', '2005-10-31 12:57:22.000000', NULL, 1),
(1827041, 249985, 43400, '<td valign="top">Outta this world stuff I like--Curious to know how it''s done. Good colors too.</td>', 'Outta this world stuff I like--Curious to know how it''s done. Good colors too.', '2005-10-31 12:58:28.000000', NULL, 1),
(1827044, 250759, 43400, '<td valign="top">Unique brilliant color and textures--I like it. Not to be too technical, but I think this is more translucent that transparent, nonetheless--It''s a great image.</td>', 'Unique brilliant color and textures--I like it. Not to be too technical, but I think this is more translucent that transparent, nonetheless--It''s a great image.', '2005-10-31 13:00:32.000000', NULL, 1),
(1827052, 251435, 8455, '<td valign="top">i really like this image, especially that the reflection has some detail in it.  The guy looks to me, like he''s smiling... happy to be out and about and photographed.  -10 (for sheer coolness)</td>', 'i really like this image, especially that the reflection has some detail in it.  The guy looks to me, like he''s smiling... happy to be out and about and photographed.  -10 (for sheer coolness)', '2005-10-31 13:04:08.000000', NULL, 1),
(1827054, 248955, 43400, '<td valign="top">Interesting capture, but I think it''s more reflective than transparent--Probably if  the glass insert was more of a focus showing the holographic "mood" aspect it would be more convincing.</td>', 'Interesting capture, but I think it''s more reflective than transparent--Probably if  the glass insert was more of a focus showing the holographic "mood" aspect it would be more convincing.', '2005-10-31 13:04:28.000000', NULL, 1),
(1827098, 251387, 44924, '<td valign="top">Straight 10 - great idea with the transparant fog. Not to mention that Wiggis &amp; Glaernisch are some of my favorite mountains in the world ;)</td>', 'Straight 10 - great idea with the transparant fog. Not to mention that Wiggis & Glaernisch are some of my favorite mountains in the world ;)', '2005-10-31 13:32:35.000000', NULL, 1),
(1827101, 250940, 24013, '<td valign="top">nice.  that fish is a star now!</td>', 'nice.  that fish is a star now!', '2005-10-31 13:35:08.000000', NULL, 1),
(1827102, 248820, 24013, '<td valign="top">excellent composition.</td>', 'excellent composition.', '2005-10-31 13:35:23.000000', NULL, 1),
(1827105, 249663, 24013, '<td valign="top">wow, i love the texture in the leaf and the mysterious nature of the shot.</td>', 'wow, i love the texture in the leaf and the mysterious nature of the shot.', '2005-10-31 13:35:52.000000', NULL, 1),
(1827108, 251200, 24013, '<td valign="top">a little on the dark - meaning scary side.  great effect.</td>', 'a little on the dark - meaning scary side.  great effect.', '2005-10-31 13:37:42.000000', NULL, 1),
(1827109, 250274, 24013, '<td valign="top">nice glow and colours.  like it a lot.</td>', 'nice glow and colours.  like it a lot.', '2005-10-31 13:38:41.000000', NULL, 1),
(1827111, 250002, 24013, '<td valign="top">very effective!</td>', 'very effective!', '2005-10-31 13:39:00.000000', NULL, 1),
(1827115, 249991, 24013, '<td valign="top">i like the texture.  interesting.  nice composition.</td>', 'i like the texture.  interesting.  nice composition.', '2005-10-31 13:40:48.000000', NULL, 1),
(1827182, 250983, 35229, '<td valign="top">Wow that is great. How well done. Love it!!! 10</td>', 'Wow that is great. How well done. Love it!!! 10', '2005-10-31 14:10:58.000000', NULL, 1),
(1827184, 250936, 16241, '<td valign="top">lovely</td>', 'lovely', '2005-10-31 14:11:48.000000', NULL, 1),
(1827187, 250452, 41675, '<td valign="top">I like the idea. For me, had there been part of the mountain in the magnifier it would be even more interesting. The hand itself is a bit too grainy for my personal taste, but nice sky.</td>', 'I like the idea. For me, had there been part of the mountain in the magnifier it would be even more interesting. The hand itself is a bit too grainy for my personal taste, but nice sky.', '2005-10-31 14:13:30.000000', NULL, 1),
(1827191, 251485, 41675, '<td valign="top">Interesting photo. My favorite part is around her nose and mouth - I think that''s because there aren''t any harsh highlights in that area.</td>', 'Interesting photo. My favorite part is around her nose and mouth - I think that''s because there aren''t any harsh highlights in that area.', '2005-10-31 14:14:46.000000', NULL, 1),
(1827193, 248820, 16241, '<td valign="top">good photo, original</td>', 'good photo, original', '2005-10-31 14:15:59.000000', NULL, 1),
(1827195, 251054, 41675, '<td valign="top">I like the shadow cast by the magnifier. For me, I find the wrinkled background a bit distracting, but a good entry.</td>', 'I like the shadow cast by the magnifier. For me, I find the wrinkled background a bit distracting, but a good entry.', '2005-10-31 14:16:25.000000', NULL, 1),
(1827196, 251454, 24212, '<td valign="top">I like the effect on the glass, but feel that the section to the left of the frame is a little unnecessary, perhaps it could be cropped off.</td>', 'I like the effect on the glass, but feel that the section to the left of the frame is a little unnecessary, perhaps it could be cropped off.', '2005-10-31 14:17:27.000000', NULL, 1),
(1827197, 250650, 41675, '<td valign="top">My favorite part is the upper left hand corner. Cool reflection. The black area in the upper right is distracting. I wonder how this would look with it completely cropped out?</td>', 'My favorite part is the upper left hand corner. Cool reflection. The black area in the upper right is distracting. I wonder how this would look with it completely cropped out?', '2005-10-31 14:17:31.000000', NULL, 1),
(1827199, 251282, 41675, '<td valign="top">Nicely done. It took my eyes a moment to find the one leaning on the tombstone as it blends in so well, but very creative. Good luck in the challenge. 9</td>', 'Nicely done. It took my eyes a moment to find the one leaning on the tombstone as it blends in so well, but very creative. Good luck in the challenge. 9', '2005-10-31 14:18:39.000000', NULL, 1),
(1827200, 250775, 24212, '<td valign="top">I think that this is a brilliant concept, wonderfully executed. The angle you''ve chosen really sets it off, as the whole effect would be a little staid if the frame were square-on.</td>', 'I think that this is a brilliant concept, wonderfully executed. The angle you''ve chosen really sets it off, as the whole effect would be a little staid if the frame were square-on.', '2005-10-31 14:18:53.000000', NULL, 1),
(1827204, 251453, 41675, '<td valign="top">Balancing act indeed! I like it. Good colors and lighting, nice reflection on the stem and pleasing composition. Well done, and good luck in the challenge.</td>', 'Balancing act indeed! I like it. Good colors and lighting, nice reflection on the stem and pleasing composition. Well done, and good luck in the challenge.', '2005-10-31 14:19:47.000000', NULL, 1),
(1827205, 250999, 24212, '<td valign="top">Quite a stark image. The monotone certainly helps emphasize that. I hope that you didn''t vandalise a ''phone box just to get a challenge entry.</td>', 'Quite a stark image. The monotone certainly helps emphasize that. I hope that you didn''t vandalise a ''phone box just to get a challenge entry.', '2005-10-31 14:20:47.000000', NULL, 1),
(1827206, 250932, 16241, '<td valign="top">nice!</td>', 'nice!', '2005-10-31 14:20:49.000000', NULL, 1),
(1827207, 251280, 41675, '<td valign="top">Nice photo. I like the setup and color treatments you chose...now I''d better go fan myself and move onto the next picture (they look like things could heat up quickly) ;-)</td>', 'Nice photo. I like the setup and color treatments you chose...now I''d better go fan myself and move onto the next picture (they look like things could heat up quickly) ;-)', '2005-10-31 14:21:08.000000', NULL, 1),
(1827210, 251273, 24212, '<td valign="top">Quite thought-provoking.</td>', 'Quite thought-provoking.', '2005-10-31 14:22:07.000000', NULL, 1),
(1827213, 250577, 41675, '<td valign="top">My favorite part of your photo is the patterns created by the plastic itself, especially in the uper left quadrant. Good entry.</td>', 'My favorite part of your photo is the patterns created by the plastic itself, especially in the uper left quadrant. Good entry.', '2005-10-31 14:22:27.000000', NULL, 1),
(1827217, 250729, 16241, '<td valign="top">wow</td>', 'wow', '2005-10-31 14:23:12.000000', NULL, 1),
(1827219, 250759, 16241, '<td valign="top">nice!</td>', 'nice!', '2005-10-31 14:23:26.000000', NULL, 1),
(1827220, 250819, 24212, '<td valign="top">I''m not too sure about the claws at the front. I''d perhaps like to see them much sharper (although I imagine that that would be a little difficult with such a close-up).</td>', 'I''m not too sure about the claws at the front. I''d perhaps like to see them much sharper (although I imagine that that would be a little difficult with such a close-up).', '2005-10-31 14:23:30.000000', NULL, 1),
(1827221, 251387, 41675, '<td valign="top">Woo-hoo, a photo with no plastic or "ghost like" people. I like it. Well done. Great capture of the sun''s light. One of my favorites, good luck in the challenge. 10</td>', 'Woo-hoo, a photo with no plastic or "ghost like" people. I like it. Well done. Great capture of the sun''s light. One of my favorites, good luck in the challenge. 10', '2005-10-31 14:23:34.000000', NULL, 1),
(1827222, 250274, 16241, '<td valign="top">very nice!</td>', 'very nice!', '2005-10-31 14:23:38.000000', NULL, 1),
(1827226, 251562, 41675, '<td valign="top">This would make a great Times Square billboard for their product. I like the different angle, although the subject matter itself doesn''t hold my interest as well as other entries in this challenge.</td>', 'This would make a great Times Square billboard for their product. I like the different angle, although the subject matter itself doesn''t hold my interest as well as other entries in this challenge.', '2005-10-31 14:24:44.000000', NULL, 1),
(1827230, 251385, 16241, '<td valign="top">wow!</td>', 'wow!', '2005-10-31 14:25:34.000000', NULL, 1),
(1827233, 250002, 41675, '<td valign="top">Points for humor and creativity.</td>', 'Points for humor and creativity.', '2005-10-31 14:26:04.000000', NULL, 1),
(1827237, 250109, 16241, '<td valign="top">great!</td>', 'great!', '2005-10-31 14:27:19.000000', NULL, 1),
(1827238, 251200, 41675, '<td valign="top">Nicely composed - gives that spooky "I''m gonna die" kind of feeling...(looks around for CSI team) :-) I''m sure this will do well in the challenge.</td>', 'Nicely composed - gives that spooky "I''m gonna die" kind of feeling...(looks around for CSI team) :-) I''m sure this will do well in the challenge.', '2005-10-31 14:27:31.000000', NULL, 1),
(1827239, 251429, 24212, '<td valign="top">The vivid colour certainly stands out, although perhaps it might be a touch too vivid ofr my tastes, especially in the lower right.</td>', 'The vivid colour certainly stands out, although perhaps it might be a touch too vivid ofr my tastes, especially in the lower right.', '2005-10-31 14:28:01.000000', NULL, 1),
(1827241, 250376, 24212, '<td valign="top">Very cleverly done, although I''d perhaps prefer to see it a little sharper.</td>', 'Very cleverly done, although I''d perhaps prefer to see it a little sharper.', '2005-10-31 14:28:36.000000', NULL, 1),
(1827242, 251168, 16241, '<td valign="top">yummy</td>', 'yummy', '2005-10-31 14:28:50.000000', NULL, 1),
(1827244, 249842, 41675, '<td valign="top">Interesting photo. I like the black and white treatment, I think color would have been less effective. For me, if there had been only one person underneath the heading on the wall - it would have been even better.</td>', 'Interesting photo. I like the black and white treatment, I think color would have been less effective. For me, if there had been only one person underneath the heading on the wall - it would have been even better.', '2005-10-31 14:29:07.000000', NULL, 1),
(1827245, 251387, 24212, '<td valign="top">Not everyone''s immediate thought when transparency is mentioned, but a great take on it nonetheless. The detail in the hillsides is astounding.</td>', 'Not everyone''s immediate thought when transparency is mentioned, but a great take on it nonetheless. The detail in the hillsides is astounding.', '2005-10-31 14:29:46.000000', NULL, 1),
(1827249, 250366, 24212, '<td valign="top">I rather like the juxtaposition of the geometric patterns of the building with the softness of the sky.</td>', 'I rather like the juxtaposition of the geometric patterns of the building with the softness of the sky.', '2005-10-31 14:30:58.000000', NULL, 1),
(1827251, 250663, 41675, '<td valign="top">Aside from the beet and pretzels, I can identify with the person asleep in the background - lol. Nicely composed. Is that a candle though? What? No peanuts? I like it. :-) 8</td>', 'Aside from the beet and pretzels, I can identify with the person asleep in the background - lol. Nicely composed. Is that a candle though? What? No peanuts? I like it. :-) 8', '2005-10-31 14:31:24.000000', NULL, 1),
(1827252, 251341, 24212, '<td valign="top">I really feel that the background does not help here. Perhaps a plain background, without the weft pattern.</td>', 'I really feel that the background does not help here. Perhaps a plain background, without the weft pattern.', '2005-10-31 14:32:00.000000', NULL, 1),
(1827253, 251341, 41675, '<td valign="top">My favorite part is the light and coloring on the quarter itself. The blue/purple gackground is probably my least favotire part.</td>', 'My favorite part is the light and coloring on the quarter itself. The blue/purple gackground is probably my least favotire part.', '2005-10-31 14:32:19.000000', NULL, 1),
