(1827793, 251550, 43400, '<td valign="top">Cool image--is that frosted ice? This may be picky, but I''d prefer not to see the leaves arranged in a circle, but in a more natural arrrangement or scattered-- very good capture.</td>', 'Cool image--is that frosted ice? This may be picky, but I''d prefer not to see the leaves arranged in a circle, but in a more natural arrrangement or scattered-- very good capture.', '2005-10-31 17:57:49.000000', NULL, 1),
(1827794, 251388, 43400, '<td valign="top">It''s tough to decipher what''s happeneing here dur to the lighting, but it looks very interesting--almost like a painting.</td>', 'It''s tough to decipher what''s happeneing here dur to the lighting, but it looks very interesting--almost like a painting.', '2005-10-31 17:59:22.000000', NULL, 1),
(1827795, 250150, 43400, '<td valign="top">Very "COOL" image and nice DOF too.</td>', 'Very "COOL" image and nice DOF too.', '2005-10-31 18:00:14.000000', NULL, 1),
(1827798, 250109, 43400, '<td valign="top">Good tranparency capture-- and great colors where was the snow?</td>', 'Good tranparency capture-- and great colors where was the snow?', '2005-10-31 18:01:12.000000', NULL, 1),
(1827805, 250671, 43400, '<td valign="top">Great journalistic capture here--I like the motion of passerby''s and the tonal coloring. I would have cropped some of the top-I find the car on upper left somewhat distracting. Great image</td>', 'Great journalistic capture here--I like the motion of passerby''s and the tonal coloring. I would have cropped some of the top-I find the car on upper left somewhat distracting. Great image', '2005-10-31 18:05:38.000000', NULL, 1),
(1827809, 251346, 43400, '<td valign="top">Ah--one of my favorites, if not THE favorite in this challenge....just a fantastic capture. The applied "snow" in frame really does it for sure--Good work</td>', 'Ah--one of my favorites, if not THE favorite in this challenge....just a fantastic capture. The applied "snow" in frame really does it for sure--Good work', '2005-10-31 18:08:18.000000', NULL, 1),
(1827811, 251531, 43400, '<td valign="top">Interesting capture--I like the transparencies through the water</td>', 'Interesting capture--I like the transparencies through the water', '2005-10-31 18:09:24.000000', NULL, 1),
(1827815, 251405, 43400, '<td valign="top">This is more like a translucent than tranparent--wish it was lighter/bright enough to maintain the mystiqueness about it--good potential.</td>', 'This is more like a translucent than tranparent--wish it was lighter/bright enough to maintain the mystiqueness about it--good potential.', '2005-10-31 18:12:32.000000', NULL, 1),
(1827819, 251403, 43400, '<td valign="top">very attractive woman--good composition too--probably could use a little more contrast</td>', 'very attractive woman--good composition too--probably could use a little more contrast', '2005-10-31 18:13:46.000000', NULL, 1),
(1827820, 250932, 43400, '<td valign="top">Interesting--though the upper portion is more appealing/ eye catching than the bottom--I would have panned the camera upwards--</td>', 'Interesting--though the upper portion is more appealing/ eye catching than the bottom--I would have panned the camera upwards--', '2005-10-31 18:16:10.000000', NULL, 1),
(1827845, 251383, 28029, '<td valign="top">Its a stretch (pun not intended) but very creative, fun and well done.8</td>', 'Its a stretch (pun not intended) but very creative, fun and well done.8', '2005-10-31 18:35:25.000000', NULL, 1),
(1827865, 249650, 46920, '<td valign="top">An absolutely beautiful picture.  Nice work.  Wish that I could be there.</td>', 'An absolutely beautiful picture.  Nice work.  Wish that I could be there.', '2005-10-31 18:42:19.000000', NULL, 1),
(1827913, 250949, 36808, '<td valign="top">can''t say exactly what it is about this that draws me, but I really like it!</td>', 'can''t say exactly what it is about this that draws me, but I really like it!', '2005-10-31 19:07:14.000000', NULL, 1),
(1827915, 250956, 36808, '<td valign="top">beautiful.</td>', 'beautiful.', '2005-10-31 19:07:33.000000', NULL, 1),
