INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1827920, 250819, 11793, '<td valign="top">hard to see the relation to transparency here.  cool crab though ;}<br/>good luck.<br/> <br/></td>', 'hard to see the relation to transparency here.  cool crab though ;}good luck. ', '2005-10-31 19:10:07.000000', NULL, 1),
(1828004, 250936, 40718, '<td valign="top">The Good: creative, in a way I like the red tint.<br/>To work on: The red is not kind on her face, mainly her left cheek.  The crease right over her eye is also not optimal.</td>', 'The Good: creative, in a way I like the red tint.To work on: The red is not kind on her face, mainly her left cheek.  The crease right over her eye is also not optimal.', '2005-10-31 19:40:31.000000', NULL, 1),
(1828009, 251282, 40718, '<td valign="top">I like this one.  That "ghost" is just right.  Very faint, yet noticeable.  Oh, I just noticed the other ghost (the one sitting).  That one is perhaps a little too dim as I almost missed it. 8</td>', 'I like this one.  That "ghost" is just right.  Very faint, yet noticeable.  Oh, I just noticed the other ghost (the one sitting).  That one is perhaps a little too dim as I almost missed it. 8', '2005-10-31 19:41:42.000000', NULL, 1),
(1828014, 250940, 40718, '<td valign="top">Heh, I almost did a shot like this.  Good for both of us I didn''t.  If I have one complaint, it''s the fish looks a bit washed out. 8</td>', 'Heh, I almost did a shot like this.  Good for both of us I didn''t.  If I have one complaint, it''s the fish looks a bit washed out. 8', '2005-10-31 19:42:24.000000', NULL, 1),
(1828018, 251501, 40718, '<td valign="top">The good: creative.<br/>To work on: it''s always nice to keep an eye unobstructed.  Could you have composed with her eye right in one bubble?  The lighting isn''t very exciting.</td>', 'The good: creative.To work on: it''s always nice to keep an eye unobstructed.  Could you have composed with her eye right in one bubble?  The lighting isn''t very exciting.', '2005-10-31 19:43:35.000000', NULL, 1),
(1828019, 251463, 40718, '<td valign="top">I like it.  If I''m being really picky I clone out the people on the left and I use a polarizer to remove the mild reflections in the windows.  Good capture though. 7</td>', 'I like it.  If I''m being really picky I clone out the people on the left and I use a polarizer to remove the mild reflections in the windows.  Good capture though. 7', '2005-10-31 19:44:22.000000', NULL, 1),
(1828020, 250361, 37875, '<td valign="top">the cars cover up a lot of the transparent windows...and the brightly lit signs (which i don''t really view as transparent) draw more of my attention in the photo...</td>', 'the cars cover up a lot of the transparent windows...and the brightly lit signs (which i don''t really view as transparent) draw more of my attention in the photo...', '2005-10-31 19:44:23.000000', NULL, 1),
(1828022, 249349, 37875, '<td valign="top">the leaves are beautiful and overpower the rain drops...the drops are so small that it''s difficult to look through them as the title suggests.  absolutely beautiful picture, with the colors and lines in the leaves.  but imo, the leaves are by far the star of this pic.</td>', 'the leaves are beautiful and overpower the rain drops...the drops are so small that it''s difficult to look through them as the title suggests.  absolutely beautiful picture, with the colors and lines in the leaves.  but imo, the leaves are by far the star of this pic.', '2005-10-31 19:44:45.000000', NULL, 1),
(1828023, 251169, 37875, '<td valign="top">what a fabulous grey sky!  and what a fun umbrella for the shot as well.  your model doesn''t look particularly angry imo, but a nicely composed shot!</td>', 'what a fabulous grey sky!  and what a fun umbrella for the shot as well.  your model doesn''t look particularly angry imo, but a nicely composed shot!', '2005-10-31 19:44:54.000000', NULL, 1),
(1828024, 250635, 37875, '<td valign="top">what a beautiful water shot!  such a great image of the fish, and such lovely light effects in the water!</td>', 'what a beautiful water shot!  such a great image of the fish, and such lovely light effects in the water!', '2005-10-31 19:44:56.000000', NULL, 1),
(1828025, 250650, 37875, '<td valign="top">nice use of transparency, with the clouds floating over the glass.  the lines and curves in the photo are interesting too. i think there''s something about the reflection that detracts for me, even though the reflection illustrates the transparency medium for you photo.  i wonder if there''s a way to keep the clouds yet knock down the glare from the reflection just a hair?</td>', 'nice use of transparency, with the clouds floating over the glass.  the lines and curves in the photo are interesting too. i think there''s something about the reflection that detracts for me, even though the reflection illustrates the transparency medium for you photo.  i wonder if there''s a way to keep the clouds yet knock down the glare from the reflection just a hair?', '2005-10-31 19:45:07.000000', NULL, 1),
(1828027, 250940, 37875, '<td valign="top">the wild thing is that the fish actually looks happy in its little room.  great photo moment!  wish the background weren''t so white...</td>', 'the wild thing is that the fish actually looks happy in its little room.  great photo moment!  wish the background weren''t so white...', '2005-10-31 19:45:12.000000', NULL, 1),
(1828028, 251385, 37875, '<td valign="top">the black thing in the upper left corner is distracting to me. nice lighting for this bowl shot, and lovely blue effect against the black background. <br/> <br/>i have to say that this photo looks familiar to me for some reason...perhaps a similar one was entered in the first transparency challenge?</td>', 'the black thing in the upper left corner is distracting to me. nice lighting for this bowl shot, and lovely blue effect against the black background.  i have to say that this photo looks familiar to me for some reason...perhaps a similar one was entered in the first transparency challenge?', '2005-10-31 19:45:16.000000', NULL, 1),
(1828029, 250977, 37875, '<td valign="top">a very nice photo!  like the light effects on the water rings...and that lone little leg pushing him along!</td>', 'a very nice photo!  like the light effects on the water rings...and that lone little leg pushing him along!', '2005-10-31 19:45:24.000000', NULL, 1),
(1828030, 250635, 40718, '<td valign="top">The good: interesting perspective on the fish, the water distorted it in an interesting way.<br/>To work on: the rest of the picture isn''t too inspiring.  You did about as much as you could with this shot, but your subject keeps you from soaring.</td>', 'The good: interesting perspective on the fish, the water distorted it in an interesting way.To work on: the rest of the picture isn''t too inspiring.  You did about as much as you could with this shot, but your subject keeps you from soaring.', '2005-10-31 19:45:25.000000', NULL, 1),
(1828031, 250938, 37875, '<td valign="top">great composition for this shot.  i''m not sure what the transparent medium adds to this photo, except for a basic structure to the photo...<br/>the subject is great, the pyramid of colors is very effective visually, and i like it!</td>', 'great composition for this shot.  i''m not sure what the transparent medium adds to this photo, except for a basic structure to the photo...the subject is great, the pyramid of colors is very effective visually, and i like it!', '2005-10-31 19:45:30.000000', NULL, 1),
(1828032, 250625, 37875, '<td valign="top">i feel afraid that this technique really starts to lose its impact when it shows up in lots of challenge themes (regardless of whether or not the photographer executed it well...)<br/> <br/>i like the distorted effect to the flowers in the drops.  many people shoot them as clear, and i appreciate the abstract effect that occurs within this shot.</td>', 'i feel afraid that this technique really starts to lose its impact when it shows up in lots of challenge themes (regardless of whether or not the photographer executed it well...) i like the distorted effect to the flowers in the drops.  many people shoot them as clear, and i appreciate the abstract effect that occurs within this shot.', '2005-10-31 19:45:32.000000', NULL, 1),
(1828033, 251126, 37875, '<td valign="top">great eye shot!  nice and clear, love the color treatment.  flawless composition.  the eye demands so much of my attention in this picture, that i question its submission for this particular challenge (because i''m interpreting your transparant focus as the contact lens, which really just disappears against the amazing image of that eye.).  absolutely gorgeous photo.</td>', 'great eye shot!  nice and clear, love the color treatment.  flawless composition.  the eye demands so much of my attention in this picture, that i question its submission for this particular challenge (because i''m interpreting your transparant focus as the contact lens, which really just disappears against the amazing image of that eye.).  absolutely gorgeous photo.', '2005-10-31 19:45:36.000000', NULL, 1),
(1828034, 250662, 37875, '<td valign="top">this feels more like an entry for "reflections without mirrors" than the current challenge to me.  lovely colors in the photo, and i would have liked to see the shot taken just a wee bit wider to allow more of the diagonal lines to flow through the photo.</td>', 'this feels more like an entry for "reflections without mirrors" than the current challenge to me.  lovely colors in the photo, and i would have liked to see the shot taken just a wee bit wider to allow more of the diagonal lines to flow through the photo.', '2005-10-31 19:45:39.000000', NULL, 1),
(1828035, 250203, 37875, '<td valign="top">like the circular cutouts in the bowl providing peekaboo glimpses of the candy.  interesting lighting approach as well.</td>', 'like the circular cutouts in the bowl providing peekaboo glimpses of the candy.  interesting lighting approach as well.', '2005-10-31 19:45:43.000000', NULL, 1),
(1828036, 249842, 37875, '<td valign="top">interesting split effect with the transparent wall!  i like the b&amp;w effect with this photo as well.</td>', 'interesting split effect with the transparent wall!  i like the b&w effect with this photo as well.', '2005-10-31 19:45:46.000000', NULL, 1),
(1828037, 249128, 37875, '<td valign="top">great detail shot of that xylem (??)!  like the composition and the blue background.  the rust colorsare a bit distracting for me, but i also don''t really know if that''s just part of the xylem or if it could be edited out.</td>', 'great detail shot of that xylem (??)!  like the composition and the blue background.  the rust colorsare a bit distracting for me, but i also don''t really know if that''s just part of the xylem or if it could be edited out.', '2005-10-31 19:45:49.000000', NULL, 1),
(1828038, 250452, 37875, '<td valign="top">sorry...you''ve got a knockout sky in this image.  that sky takes all the attention away from that magnifying glass...imo!</td>', 'sorry...you''ve got a knockout sky in this image.  that sky takes all the attention away from that magnifying glass...imo!', '2005-10-31 19:45:51.000000', NULL, 1),
(1828039, 251403, 37875, '<td valign="top">lovely portrait shot.  like the dof and soft b&amp;w.  not sure what the white dots are...beading or something?  they are a bit distracting to my eye from those eyes and that great smile!  otherwise, a beautiful photo nicely done!</td>', 'lovely portrait shot.  like the dof and soft b&w.  not sure what the white dots are...beading or something?  they are a bit distracting to my eye from those eyes and that great smile!  otherwise, a beautiful photo nicely done!', '2005-10-31 19:45:54.000000', NULL, 1),
(1828040, 251583, 37875, '<td valign="top">interesting effect from the grid.  like the bright oranges and yellows behind the frosted grid.</td>', 'interesting effect from the grid.  like the bright oranges and yellows behind the frosted grid.', '2005-10-31 19:45:58.000000', NULL, 1),
(1828042, 251353, 37875, '<td valign="top">this comes across to me more as a texture photo than an transparency photo with the water on the wood.  nice lighting, great texture, and like the nails as contrast.</td>', 'this comes across to me more as a texture photo than an transparency photo with the water on the wood.  nice lighting, great texture, and like the nails as contrast.', '2005-10-31 19:46:00.000000', NULL, 1),
(1828043, 250994, 37875, '<td valign="top">the water drops actually stand out a bit in this photo for me...most have been getting lost within the picture.</td>', 'the water drops actually stand out a bit in this photo for me...most have been getting lost within the picture.', '2005-10-31 19:46:07.000000', NULL, 1),
(1828044, 250854, 37875, '<td valign="top">the pool divider directs my eye away from the submerged swimmer...i think this would be a stronger image without the pool divider, and with a closer shot of the swimmer.</td>', 'the pool divider directs my eye away from the submerged swimmer...i think this would be a stronger image without the pool divider, and with a closer shot of the swimmer.', '2005-10-31 19:46:11.000000', NULL, 1),
(1828045, 250453, 37875, '<td valign="top">this strikes me more as reflective than transparant...<br/> <br/>that aside, a polarizing filter may have helped remove the glare in the window reflection for a clearer shot of the photographer.</td>', 'this strikes me more as reflective than transparant... that aside, a polarizing filter may have helped remove the glare in the window reflection for a clearer shot of the photographer.', '2005-10-31 19:46:14.000000', NULL, 1),
(1828046, 251341, 37875, '<td valign="top">love the gold tones caused by the light in the juice.  like the choice of purple for the background.  it''s a nitpicky thing, but i kind of wish that i couldn''t see so much of the knit in the background fabric.  but really, the quarter shot is lovely.</td>', 'love the gold tones caused by the light in the juice.  like the choice of purple for the background.  it''s a nitpicky thing, but i kind of wish that i couldn''t see so much of the knit in the background fabric.  but really, the quarter shot is lovely.', '2005-10-31 19:46:17.000000', NULL, 1),
(1828047, 251280, 37875, '<td valign="top">a lovely composition.  i like how red the rose is, and i like the subtlety of the mesh top on the woman.  the white background feels a bit harsh for such a soft-feeling photo to me, though.</td>', 'a lovely composition.  i like how red the rose is, and i like the subtlety of the mesh top on the woman.  the white background feels a bit harsh for such a soft-feeling photo to me, though.', '2005-10-31 19:46:19.000000', NULL, 1),
(1828048, 251359, 37875, '<td valign="top">a nice idea.  i would have liked to see a less-harsh background for this pic.</td>', 'a nice idea.  i would have liked to see a less-harsh background for this pic.', '2005-10-31 19:46:25.000000', NULL, 1),
(1828049, 251429, 37875, '<td valign="top">like the choice of subject and how the light treats it.</td>', 'like the choice of subject and how the light treats it.', '2005-10-31 19:46:29.000000', NULL, 1),
(1828050, 251453, 37875, '<td valign="top">a lovely photo, with elegant lines and curves.  i like the contrast with the brownish-red liquid.</td>', 'a lovely photo, with elegant lines and curves.  i like the contrast with the brownish-red liquid.', '2005-10-31 19:46:32.000000', NULL, 1),
(1828051, 248870, 37875, '<td valign="top">fun pic with the bubbles floating out of the glass...</td>', 'fun pic with the bubbles floating out of the glass...', '2005-10-31 19:46:38.000000', NULL, 1),
(1828052, 251200, 37875, '<td valign="top">well done!  a great idea, nicely executed.  good luck!</td>', 'well done!  a great idea, nicely executed.  good luck!', '2005-10-31 19:46:42.000000', NULL, 1),
(1828053, 251197, 37875, '<td valign="top">makes me miss my pearlie mae grundoon!  great concept, nicely executed.</td>', 'makes me miss my pearlie mae grundoon!  great concept, nicely executed.', '2005-10-31 19:46:45.000000', NULL, 1),
(1828054, 251460, 37875, '<td valign="top">nice choice for transparancy!  would have liked to see a sharper image of the eye in the magnifying glass...</td>', 'nice choice for transparancy!  would have liked to see a sharper image of the eye in the magnifying glass...', '2005-10-31 19:46:49.000000', NULL, 1),
