(1828263, 250434, 41675, '<td valign="top">Nice geometric shapes and I like the softness created by the colors and lighting. I could see this as an oversize color print in some high class spa. :-)</td>', 'Nice geometric shapes and I like the softness created by the colors and lighting. I could see this as an oversize color print in some high class spa. :-)', '2005-10-31 20:17:17.000000', NULL, 1),
(1828266, 250671, 41675, '<td valign="top">Interesting and thought provoking title. I like the "ghosted" legs and feet around her. I find the car in the background a bit distracting, but sometimes you can''t help that stuff. Nice job.</td>', 'Interesting and thought provoking title. I like the "ghosted" legs and feet around her. I find the car in the background a bit distracting, but sometimes you can''t help that stuff. Nice job.', '2005-10-31 20:18:41.000000', NULL, 1),
(1828269, 248955, 41675, '<td valign="top">Not a bad idea. I think maybe a better reflecting surface, less noise/grain and a bit more sharpness around the ring itself would enhance the photo. Also, for me, I find that when the main subject is off-centered it adds more interest.</td>', 'Not a bad idea. I think maybe a better reflecting surface, less noise/grain and a bit more sharpness around the ring itself would enhance the photo. Also, for me, I find that when the main subject is off-centered it adds more interest.', '2005-10-31 20:20:11.000000', NULL, 1),
(1828271, 251051, 41675, '<td valign="top">Neat concept. I''ve been looking at it for a few moments now. For me, I wonder how this would look with the stem of the glass completely cropped off. I tried it with my hand and liked it better, but that''s just me.</td>', 'Neat concept. I''ve been looking at it for a few moments now. For me, I wonder how this would look with the stem of the glass completely cropped off. I tried it with my hand and liked it better, but that''s just me.', '2005-10-31 20:21:33.000000', NULL, 1),
(1828313, 251458, 41675, '<td valign="top">Nice, simple composition. The leaf seems out if it''s natural element - I keep thinking it''s in a sink or bathtub. I do like the broken stem part though. That area of your photo is my favorite.</td>', 'Nice, simple composition. The leaf seems out if it''s natural element - I keep thinking it''s in a sink or bathtub. I do like the broken stem part though. That area of your photo is my favorite.', '2005-10-31 20:37:22.000000', NULL, 1),
(1828316, 251429, 41675, '<td valign="top">Your photo has a graphic appeal to it. For me, it would work well for an alcohol ad campaign. Cool colors (ha ha, no pun intended), and I like the off centered composition. Good luck in the challenge. 8</td>', 'Your photo has a graphic appeal to it. For me, it would work well for an alcohol ad campaign. Cool colors (ha ha, no pun intended), and I like the off centered composition. Good luck in the challenge. 8', '2005-10-31 20:38:27.000000', NULL, 1),
(1828320, 250759, 41675, '<td valign="top">Nice macro and good colors. Makes me think of warmth and sunshine. 7</td>', 'Nice macro and good colors. Makes me think of warmth and sunshine. 7', '2005-10-31 20:39:37.000000', NULL, 1),
(1828324, 250203, 41675, '<td valign="top">I like your idea. For me, if it was a bit sharper overall (yeah, I''m one of those that prefers crisp images) I would have scored it higher. I do like how you can see the candies inside - kind of like individual little pods or something - cool effect.</td>', 'I like your idea. For me, if it was a bit sharper overall (yeah, I''m one of those that prefers crisp images) I would have scored it higher. I do like how you can see the candies inside - kind of like individual little pods or something - cool effect.', '2005-10-31 20:40:50.000000', NULL, 1),
(1828328, 249349, 41675, '<td valign="top">The colors seem a bit over saturated to me, but I like the composition.</td>', 'The colors seem a bit over saturated to me, but I like the composition.', '2005-10-31 20:42:10.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1828332, 251456, 41675, '<td valign="top">I like the shadow and the coloring on the foreground scissor(?) handle. The white backgroudn is a bit stark and takes away from the warmth of the object and shadow, but a nice change of pace from other entries. Shows creativity.</td>', 'I like the shadow and the coloring on the foreground scissor(?) handle. The white backgroudn is a bit stark and takes away from the warmth of the object and shadow, but a nice change of pace from other entries. Shows creativity.', '2005-10-31 20:44:16.000000', NULL, 1),
(1828333, 250819, 41675, '<td valign="top">Wow - neat closeup of the little guy - hope it wasn''t about to become someone''s meal (poor thing). You did so well focusing on it, it''s hard for me to see the transparency part, but I know mentally it''s there...just not visually.</td>', 'Wow - neat closeup of the little guy - hope it wasn''t about to become someone''s meal (poor thing). You did so well focusing on it, it''s hard for me to see the transparency part, but I know mentally it''s there...just not visually.', '2005-10-31 20:45:26.000000', NULL, 1),
(1828336, 250563, 41675, '<td valign="top">Good store shot. For me, I wish the lighting wasn''t quite as yellowish, but again, well done.</td>', 'Good store shot. For me, I wish the lighting wasn''t quite as yellowish, but again, well done.', '2005-10-31 20:46:31.000000', NULL, 1),
(1828338, 249663, 41675, '<td valign="top">Now that''s a transparent shot! So...how many times did you have to bribe it...or is it even real? Hmmm...anyhow - cleverly done and well executed. Hope you get a ribbon! 10</td>', 'Now that''s a transparent shot! So...how many times did you have to bribe it...or is it even real? Hmmm...anyhow - cleverly done and well executed. Hope you get a ribbon! 10', '2005-10-31 20:47:21.000000', NULL, 1),
(1828341, 251267, 41675, '<td valign="top">Wow - really freaky eyes. Good bug macro though. I like the composition and lighting.</td>', 'Wow - really freaky eyes. Good bug macro though. I like the composition and lighting.', '2005-10-31 20:48:03.000000', NULL, 1),
(1828342, 251568, 41675, '<td valign="top">A good idea, but your image is coming across as pixelated on my screen, whereas other entries in the challenge have not. I also wonder how this would look as a black and white photo with a bit more contrast?</td>', 'A good idea, but your image is coming across as pixelated on my screen, whereas other entries in the challenge have not. I also wonder how this would look as a black and white photo with a bit more contrast?', '2005-10-31 20:49:09.000000', NULL, 1),
(1828344, 251438, 41675, '<td valign="top">Ha, ha ha! Good one - at least to those of us "old" enough to understand...ha ha ha.</td>', 'Ha, ha ha! Good one - at least to those of us "old" enough to understand...ha ha ha.', '2005-10-31 20:50:06.000000', NULL, 1),
(1828348, 250879, 41675, '<td valign="top">I think I understand where you are coming from with your title - but for me it''s stretching it a bit. Compared with other entries in this challenge with more obvious and visual transparencies, I have scored this lower, even though I do see the eyes themselves.</td>', 'I think I understand where you are coming from with your title - but for me it''s stretching it a bit. Compared with other entries in this challenge with more obvious and visual transparencies, I have scored this lower, even though I do see the eyes themselves.', '2005-10-31 20:52:24.000000', NULL, 1),
(1828349, 251423, 41675, '<td valign="top">I like it. Good black and white image. I would have liked to have seen her entire head, but again, well done.</td>', 'I like it. Good black and white image. I would have liked to have seen her entire head, but again, well done.', '2005-10-31 20:53:04.000000', NULL, 1),
(1828357, 250741, 31403, '<td valign="top">the falls are very pretty, but the "stuff" in the right part of the frame doesn''t add anything to it, I would have preferred you crop right down to just the falls</td>', 'the falls are very pretty, but the "stuff" in the right part of the frame doesn''t add anything to it, I would have preferred you crop right down to just the falls', '2005-10-31 20:57:55.000000', NULL, 1),
(1828361, 250435, 31403, '<td valign="top">crop right in there - don''t show us it''s a monitor - you have a neat illusion here - you just gave it away - 4</td>', 'crop right in there - don''t show us it''s a monitor - you have a neat illusion here - you just gave it away - 4', '2005-10-31 21:00:27.000000', NULL, 1),
(1828362, 251423, 31403, '<td valign="top">more contrast please</td>', 'more contrast please', '2005-10-31 21:00:46.000000', NULL, 1),
(1828372, 251311, 31403, '<td valign="top">lose the door frame and just shoot through the glass and I''ll give you a 10 - love this - almost.  Seems like the whites could be a little brighter too.  Great creative - 6</td>', 'lose the door frame and just shoot through the glass and I''ll give you a 10 - love this - almost.  Seems like the whites could be a little brighter too.  Great creative - 6', '2005-10-31 21:08:20.000000', NULL, 1),
(1828418, 251405, 33515, '<td valign="top">I wonder how many people see only black, very bold to enter this in a world of uncalibrated monitors. Best of luck</td>', 'I wonder how many people see only black, very bold to enter this in a world of uncalibrated monitors. Best of luck', '2005-10-31 21:27:33.000000', NULL, 1),
(1828419, 250002, 36619, '<td valign="top">whoa! cool.</td>', 'whoa! cool.', '2005-10-31 21:27:35.000000', NULL, 1),
(1828430, 251453, 40718, '<td valign="top">Creative and I like the gradient on the background.  I think the color scheme keeps it from being top notch, but still quite nice. 8</td>', 'Creative and I like the gradient on the background.  I think the color scheme keeps it from being top notch, but still quite nice. 8', '2005-10-31 21:34:47.000000', NULL, 1),
(1828441, 251485, 5112, '<td valign="top">Hmmmm .... Mariana?  If not, I''ll be terribly embarrassed.  Apologies in advance if this is not "funnylooks".</td>', 'Hmmmm .... Mariana?  If not, I''ll be terribly embarrassed.  Apologies in advance if this is not "funnylooks".', '2005-10-31 21:40:33.000000', NULL, 1),
(1828467, 249432, 8624, '<td valign="top">nice idea. I don''t like the big white glare in her eye, though.</td>', 'nice idea. I don''t like the big white glare in her eye, though.', '2005-10-31 21:57:19.000000', NULL, 1),
(1828471, 250109, 40718, '<td valign="top">I like the color of the twilight sky.  It''s a creative idea.  The electrical lines and such don''t add too much, but perhaps there was little choice as to where to take the picture. 7</td>', 'I like the color of the twilight sky.  It''s a creative idea.  The electrical lines and such don''t add too much, but perhaps there was little choice as to where to take the picture. 7', '2005-10-31 22:00:43.000000', NULL, 1),
(1828472, 251368, 40718, '<td valign="top">Natural frames like this are nice.  I might have cropped to a slightly less thick outer frame.</td>', 'Natural frames like this are nice.  I might have cropped to a slightly less thick outer frame.', '2005-10-31 22:01:18.000000', NULL, 1),
(1828473, 251274, 40718, '<td valign="top">Cute expression on the girl.  The B&amp;W processing is nice. 7</td>', 'Cute expression on the girl.  The B&W processing is nice. 7', '2005-10-31 22:01:45.000000', NULL, 1),
(1828474, 249507, 40718, '<td valign="top">Well, I''m not too sure I like the composition.  The subject has too little interaction with the telescope.  Why are the two in the same picture? and why is she transparent?  the technicals are nice though.</td>', 'Well, I''m not too sure I like the composition.  The subject has too little interaction with the telescope.  Why are the two in the same picture? and why is she transparent?  the technicals are nice though.', '2005-10-31 22:02:53.000000', NULL, 1),
(1828478, 249842, 40718, '<td valign="top">I think this is really cute and well done.  At first I thought it was a transparent glass on an moving walkway.  If it is, it still has boucoup processing.  The interface between the blur and the rail could have been better with jaggies all over (could have been the resizing too). 6</td>', 'I think this is really cute and well done.  At first I thought it was a transparent glass on an moving walkway.  If it is, it still has boucoup processing.  The interface between the blur and the rail could have been better with jaggies all over (could have been the resizing too). 6', '2005-10-31 22:04:39.000000', NULL, 1),
(1828479, 250875, 40718, '<td valign="top">Nice concept.  I like the blue, but not too fond of the pink. 6</td>', 'Nice concept.  I like the blue, but not too fond of the pink. 6', '2005-10-31 22:05:06.000000', NULL, 1),
(1828483, 248989, 40718, '<td valign="top">Not having second curtain sync always makes for a confusing picture.  I like the concept, but I don''t think it panned out for you.</td>', 'Not having second curtain sync always makes for a confusing picture.  I like the concept, but I don''t think it panned out for you.', '2005-10-31 22:06:14.000000', NULL, 1),
(1828486, 249432, 40718, '<td valign="top">Whew, beautiful eye, isn''t it?  The mimosa could leave a little to be desired colorwise, but it''s a nice concept.</td>', 'Whew, beautiful eye, isn''t it?  The mimosa could leave a little to be desired colorwise, but it''s a nice concept.', '2005-10-31 22:06:59.000000', NULL, 1),
(1828487, 251303, 40718, '<td valign="top">I''m not quite sure what to think about this one.  An interesting concept, but not that appealing.  Would I want this on a wall?</td>', 'I''m not quite sure what to think about this one.  An interesting concept, but not that appealing.  Would I want this on a wall?', '2005-10-31 22:07:37.000000', NULL, 1),
(1828488, 251583, 40718, '<td valign="top">Nice in an abstract sort of way.  The colors are fairly pleasing.</td>', 'Nice in an abstract sort of way.  The colors are fairly pleasing.', '2005-10-31 22:08:12.000000', NULL, 1),
(1828489, 251402, 40718, '<td valign="top">Great expression and I like the shadowplay. 7</td>', 'Great expression and I like the shadowplay. 7', '2005-10-31 22:08:27.000000', NULL, 1),
(1828492, 250938, 40718, '<td valign="top">I like taking pictures of ordinary things arranged in a way to make you look again.  Hope you are a teacher and had those markers just laying around...</td>', 'I like taking pictures of ordinary things arranged in a way to make you look again.  Hope you are a teacher and had those markers just laying around...', '2005-10-31 22:09:09.000000', NULL, 1),
(1828495, 251197, 40718, '<td valign="top">The blurring of the couch arm was the first thing that caught my eye.  It''s a nice concept and fairly well pulled off.</td>', 'The blurring of the couch arm was the first thing that caught my eye.  It''s a nice concept and fairly well pulled off.', '2005-10-31 22:09:57.000000', NULL, 1),
(1828497, 251364, 40718, '<td valign="top">The lighting is a little overdone or she has a lot of foundation on.  It''s a nice tight composition, but I''m left uninspired. 6</td>', 'The lighting is a little overdone or she has a lot of foundation on.  It''s a nice tight composition, but I''m left uninspired. 6', '2005-10-31 22:10:59.000000', NULL, 1),
(1828498, 251044, 40718, '<td valign="top">Creative.  The globe is nice and sharp. 7</td>', 'Creative.  The globe is nice and sharp. 7', '2005-10-31 22:11:26.000000', NULL, 1),
(1828503, 250879, 40718, '<td valign="top">She looks like she''s been hanging out with Joey too much.  You are probably going to get a lot of "where''s the transparency" cuz it took me more than 5 seconds to see it.  Freaky once I did.  Really freaky...7</td>', 'She looks like she''s been hanging out with Joey too much.  You are probably going to get a lot of "where''s the transparency" cuz it took me more than 5 seconds to see it.  Freaky once I did.  Really freaky...7', '2005-10-31 22:12:53.000000', NULL, 1),
(1828506, 251279, 40718, '<td valign="top">Always good for a laugh, but not a really high score. :(</td>', 'Always good for a laugh, but not a really high score. :(', '2005-10-31 22:13:24.000000', NULL, 1),
(1828509, 251455, 40718, '<td valign="top">the subject isn''t all that great to me.</td>', 'the subject isn''t all that great to me.', '2005-10-31 22:14:06.000000', NULL, 1),
(1828510, 250977, 40718, '<td valign="top">ain''t ducklings cute?  it looks overexposed though.</td>', 'ain''t ducklings cute?  it looks overexposed though.', '2005-10-31 22:14:30.000000', NULL, 1),
(1828511, 250819, 40718, '<td valign="top">that''s some clear glass.  Nice semi-macro capture. 7</td>', 'that''s some clear glass.  Nice semi-macro capture. 7', '2005-10-31 22:14:52.000000', NULL, 1),
(1828512, 250918, 40718, '<td valign="top">abstractly nice.</td>', 'abstractly nice.', '2005-10-31 22:15:21.000000', NULL, 1),
(1828515, 251168, 40718, '<td valign="top">mmm, peppers.  The perspective is creative, but I''m not sure it is the best one.  It''s also too bad I can see the detail in the background. 6</td>', 'mmm, peppers.  The perspective is creative, but I''m not sure it is the best one.  It''s also too bad I can see the detail in the background. 6', '2005-10-31 22:16:14.000000', NULL, 1),
(1828516, 251501, 23430, '<td valign="top">Hey this is really different. I like the toned down colours in the face (wether it''s deliberate or not)</td>', 'Hey this is really different. I like the toned down colours in the face (wether it''s deliberate or not)', '2005-10-31 22:16:37.000000', NULL, 1),
(1828519, 250940, 23430, '<td valign="top">Neat concept and composition</td>', 'Neat concept and composition', '2005-10-31 22:17:31.000000', NULL, 1),
(1828521, 251268, 40718, '<td valign="top">what am I looking at?  it''s a weird glass, but that''s what I think it is.  I''m not sure the distortion is kind to her face, but your title implies you want to "trip us out". 6</td>', 'what am I looking at?  it''s a weird glass, but that''s what I think it is.  I''m not sure the distortion is kind to her face, but your title implies you want to "trip us out". 6', '2005-10-31 22:18:10.000000', NULL, 1),
(1828525, 251353, 23430, '<td valign="top">I know there''s transparency here but it doesn''t stand out. Tidy composition otherwise</td>', 'I know there''s transparency here but it doesn''t stand out. Tidy composition otherwise', '2005-10-31 22:19:02.000000', NULL, 1),
(1828526, 251387, 40718, '<td valign="top">Nice landscape.  The border is distracting...haha...I just say that cuz  it makes you sound smart.  I think the border is fine. 7</td>', 'Nice landscape.  The border is distracting...haha...I just say that cuz  it makes you sound smart.  I think the border is fine. 7', '2005-10-31 22:19:21.000000', NULL, 1),
(1828527, 250689, 40718, '<td valign="top">Creative.  It''s a nice architectural subject.</td>', 'Creative.  It''s a nice architectural subject.', '2005-10-31 22:19:41.000000', NULL, 1),
(1828529, 251368, 23430, '<td valign="top">I like how you''ve cropped to the window frame it looks like I''m looking out through my monitor</td>', 'I like how you''ve cropped to the window frame it looks like I''m looking out through my monitor', '2005-10-31 22:21:31.000000', NULL, 1),
(1828530, 250741, 40718, '<td valign="top">A fellow Oregonian?  The water is nice and smooth.  I''ve found that falls which don''t "ripple" down rock don''t look quite as nice because the blur becomes quite uniform.  I''ll have to visit this one though...7</td>', 'A fellow Oregonian?  The water is nice and smooth.  I''ve found that falls which don''t "ripple" down rock don''t look quite as nice because the blur becomes quite uniform.  I''ll have to visit this one though...7', '2005-10-31 22:21:52.000000', NULL, 1),
(1828532, 251402, 23430, '<td valign="top">Well composed and cute kid.</td>', 'Well composed and cute kid.', '2005-10-31 22:22:29.000000', NULL, 1),
(1828533, 251267, 40718, '<td valign="top">Great capture.  I love mantises (manti?).  I''m not sure how transparent it is, but I''ll let others worry about that. It''s a little overexposed. 6</td>', 'Great capture.  I love mantises (manti?).  I''m not sure how transparent it is, but I''ll let others worry about that. It''s a little overexposed. 6', '2005-10-31 22:22:38.000000', NULL, 1),
(1828535, 250002, 23430, '<td valign="top">Bazarre</td>', 'Bazarre', '2005-10-31 22:23:06.000000', NULL, 1),
(1828536, 251550, 40718, '<td valign="top">Creative, but it winds up not translating to picture too well.  I think it winds up looking too artificial with the arrangement of the leaves.</td>', 'Creative, but it winds up not translating to picture too well.  I think it winds up looking too artificial with the arrangement of the leaves.', '2005-10-31 22:23:36.000000', NULL, 1),
(1828542, 250434, 40718, '<td valign="top">You trying to give me flashbacks of light on white?  I want that challenge long behind me.  It''s a nice abstract, but maybe a little too ethereal. 6</td>', 'You trying to give me flashbacks of light on white?  I want that challenge long behind me.  It''s a nice abstract, but maybe a little too ethereal. 6', '2005-10-31 22:25:51.000000', NULL, 1),
(1828546, 251010, 40718, '<td valign="top">Hmmm, a little too invisible in my opinion.  Makes it look two dimensional.  But creative concept. 6</td>', 'Hmmm, a little too invisible in my opinion.  Makes it look two dimensional.  But creative concept. 6', '2005-10-31 22:26:40.000000', NULL, 1),
(1828548, 250088, 40718, '<td valign="top">Dang! Another light on white flashback.  I''m not sure I catch the transparency here as the pic is too processed.</td>', 'Dang! Another light on white flashback.  I''m not sure I catch the transparency here as the pic is too processed.', '2005-10-31 22:27:25.000000', NULL, 1),
(1828554, 251020, 35218, '<td valign="top">First photo to come up on my screen for voting and it''s marvellous.  Well done.</td>', 'First photo to come up on my screen for voting and it''s marvellous.  Well done.', '2005-10-31 22:29:49.000000', NULL, 1),
(1828557, 249981, 40718, '<td valign="top">Great capture.  This is a top 5 if not a ribbon.  I''m guessing this took some nice equipment because you are using a) macro b) have a nice thick depth of field and c) froze the motion very well.  Hmmm, now that I think about it, I don''t think this actually is what we are meant to think it is.  The two tiny drops on the large globe I think give it away.  Also, in my experience of shots like this, the drop is too big compared to the column.  Still a great imitation. 10</td>', 'Great capture.  This is a top 5 if not a ribbon.  I''m guessing this took some nice equipment because you are using a) macro b) have a nice thick depth of field and c) froze the motion very well.  Hmmm, now that I think about it, I don''t think this actually is what we are meant to think it is.  The two tiny drops on the large globe I think give it away.  Also, in my experience of shots like this, the drop is too big compared to the column.  Still a great imitation. 10', '2005-10-31 22:30:33.000000', NULL, 1),
(1828558, 251409, 40718, '<td valign="top">is that image grain? that challenge is over and DPC is all smooth - all the time.  Just kidding.  I can''t say I''m too excited about this picture though.  Just not that great a subject.</td>', 'is that image grain? that challenge is over and DPC is all smooth - all the time.  Just kidding.  I can''t say I''m too excited about this picture though.  Just not that great a subject.', '2005-10-31 22:31:26.000000', NULL, 1),
(1828559, 251280, 40718, '<td valign="top">Nice concept and well processed.  I don''t think it''s quite my style, but I won''t hold that against you. 8</td>', 'Nice concept and well processed.  I don''t think it''s quite my style, but I won''t hold that against you. 8', '2005-10-31 22:32:58.000000', NULL, 1),
(1828560, 251288, 40718, '<td valign="top">great lightplay. sharp focus.</td>', 'great lightplay. sharp focus.', '2005-10-31 22:33:17.000000', NULL, 1),
(1828562, 251438, 40718, '<td valign="top">I''m starting to grow bored of the picture within a picture, but I won''t hold it against you...yet.  The OOF filter is nicely done. 7</td>', 'I''m starting to grow bored of the picture within a picture, but I won''t hold it against you...yet.  The OOF filter is nicely done. 7', '2005-10-31 22:34:11.000000', NULL, 1),
(1828563, 248820, 35218, '<td valign="top">Very nnicely done.</td>', 'Very nnicely done.', '2005-10-31 22:34:27.000000', NULL, 1),
(1828564, 250123, 40718, '<td valign="top">Nice macro.  The lighting could be a little more dynamic to put it over the top, but still not bad.</td>', 'Nice macro.  The lighting could be a little more dynamic to put it over the top, but still not bad.', '2005-10-31 22:34:39.000000', NULL, 1),
(1828610, 251463, 3554, '<td valign="top">The whole picture has a bluish or greenish tint as though the white balance is off. Good choice of subject.</td>', 'The whole picture has a bluish or greenish tint as though the white balance is off. Good choice of subject.', '2005-10-31 22:57:25.000000', NULL, 1),
(1828632, 250453, 3554, '<td valign="top">There''s just nothing in this picture to hold my interest. Yes it fits the challenge (assuming that you took it through a closed car window) but the angle, lighting, etc, just do nothing to draw your audience in.</td>', 'There''s just nothing in this picture to hold my interest. Yes it fits the challenge (assuming that you took it through a closed car window) but the angle, lighting, etc, just do nothing to draw your audience in.', '2005-10-31 23:06:33.000000', NULL, 1),
(1828635, 250361, 3554, '<td valign="top">I think if you could have come and shot this at a time when there weren''t any cars parked in front of the stores it would have had a better impact. As it is the cars block a lot of your subject (the windows) and take away from the picture.</td>', 'I think if you could have come and shot this at a time when there weren''t any cars parked in front of the stores it would have had a better impact. As it is the cars block a lot of your subject (the windows) and take away from the picture.', '2005-10-31 23:07:58.000000', NULL, 1),
