(1837048, 250879, 7485, '<td valign="top">Creepy and very well done. Unfortunately doesn''t seem to fit the challenge, but darn good anyway.</td>', 'Creepy and very well done. Unfortunately doesn''t seem to fit the challenge, but darn good anyway.', '2005-11-03 23:04:22.000000', NULL, 1),
