(1837533, 251044, 43115, '<td valign="top">Technically very well done, but I don''t see transparency, only reflection...</td>', 'Technically very well done, but I don''t see transparency, only reflection...', '2005-11-04 08:31:18.000000', NULL, 1),
(1837537, 251405, 43115, '<td valign="top">Much too dark.  A flash unit (even just a little bit) behind the door with the model would have made this much better.  I''m not saying he has to be perfectly lit, but this is too far towards dark.</td>', 'Much too dark.  A flash unit (even just a little bit) behind the door with the model would have made this much better.  I''m not saying he has to be perfectly lit, but this is too far towards dark.', '2005-11-04 08:32:51.000000', NULL, 1),
(1837541, 251010, 43115, '<td valign="top">I understand the concept, but this is just too blown out for me to really like it.  It looks like the labels are just floating in mid-air.  The tranparency is lost, as the bottle really looks invisible.</td>', 'I understand the concept, but this is just too blown out for me to really like it.  It looks like the labels are just floating in mid-air.  The tranparency is lost, as the bottle really looks invisible.', '2005-11-04 08:34:15.000000', NULL, 1),
(1837542, 248955, 43115, '<td valign="top">Reflection?  This doesn''t say "transparency" to me.</td>', 'Reflection?  This doesn''t say "transparency" to me.', '2005-11-04 08:35:01.000000', NULL, 1),
(1837544, 250453, 43115, '<td valign="top">Reflection is not transparency.</td>', 'Reflection is not transparency.', '2005-11-04 08:35:25.000000', NULL, 1),
(1837549, 250819, 43115, '<td valign="top">I understand that the critter is in a tank, behind transparent glass.  But the point of this challenge was to <i>show</i> transparency.  Without the title I wouldn''t know that there was transparency here.  Nice macro, but not a strong enough tie to the challenge for my taste.</td>', 'I understand that the critter is in a tank, behind transparent glass.  But the point of this challenge was to show transparency.  Without the title I wouldn''t know that there was transparency here.  Nice macro, but not a strong enough tie to the challenge for my taste.', '2005-11-04 08:38:43.000000', NULL, 1),
(1837647, 250002, 45897, '<td valign="top">Cool picture......made me laugh also.</td>', 'Cool picture......made me laugh also.', '2005-11-04 09:52:33.000000', NULL, 1),
