(1837719, 250875, 42638, '<td valign="top">Wonderful coloring, nice shapes. Lovely picture.</td>', 'Wonderful coloring, nice shapes. Lovely picture.', '2005-11-04 10:50:08.000000', NULL, 1),
(1837724, 250940, 42638, '<td valign="top">Too Cute! Very nicely done. Love the color and simplicity. Great rule of 3rds.</td>', 'Too Cute! Very nicely done. Love the color and simplicity. Great rule of 3rds.', '2005-11-04 10:51:44.000000', NULL, 1),
