(1841786, 251403, 39850, '<td valign="top">8 - Very nice.  Criticism; not much, maybe a slightly different crop, not sure.</td>', '8 - Very nice.  Criticism; not much, maybe a slightly different crop, not sure.', '2005-11-06 07:07:05.000000', NULL, 1),
(1841787, 249981, 39850, '<td valign="top">8 - Good and ''interesting''.  Criticism; difficult, but maybe more colors, if apt.  Seems a slight ''gamma'' type issue with the colors surrounding the black, but could be my monitor.</td>', '8 - Good and ''interesting''.  Criticism; difficult, but maybe more colors, if apt.  Seems a slight ''gamma'' type issue with the colors surrounding the black, but could be my monitor.', '2005-11-06 07:08:11.000000', NULL, 1),
(1841788, 251039, 39850, '<td valign="top">7 - Good idea.  Criticism; maybe a slight nudge rotation up on the right, to straighten.  Difficult to say anything else as am not sure how you did this.</td>', '7 - Good idea.  Criticism; maybe a slight nudge rotation up on the right, to straighten.  Difficult to say anything else as am not sure how you did this.', '2005-11-06 07:09:13.000000', NULL, 1),
(1841789, 251438, 39850, '<td valign="top">7 - Good idea and has humor.  Criticism; not much, maybe a different crop, centering the frames more, and perhaps a different placement of the glasses so more befitting words appear in the left lens, depending of course what is there.</td>', '7 - Good idea and has humor.  Criticism; not much, maybe a different crop, centering the frames more, and perhaps a different placement of the glasses so more befitting words appear in the left lens, depending of course what is there.', '2005-11-06 07:10:31.000000', NULL, 1),
(1841792, 251412, 39850, '<td valign="top">7 - Like the concept.  Criticism; not much, just doesn''t ''pop out'' as much as I would like to see it, difficult against the water, but befitting for the Challenge.  Nice ''combinations'' of elements.</td>', '7 - Like the concept.  Criticism; not much, just doesn''t ''pop out'' as much as I would like to see it, difficult against the water, but befitting for the Challenge.  Nice ''combinations'' of elements.', '2005-11-06 07:11:27.000000', NULL, 1),
(1841793, 251346, 39850, '<td valign="top">7 - Good.  Criticism; not much, maybe a slightly different angle with the frame, not sure.  Colors a little more vivid too, may have made this better in my opinion.  Like the nice sharp angle/perspective.</td>', '7 - Good.  Criticism; not much, maybe a slightly different angle with the frame, not sure.  Colors a little more vivid too, may have made this better in my opinion.  Like the nice sharp angle/perspective.', '2005-11-06 07:12:44.000000', NULL, 1),
(1841796, 251550, 39850, '<td valign="top">7 - Good idea.  Criticism; especially for the Challenge, would like to have been able to discern more ''transparency'', ''glass like'' of the ice, but difficult to do I imagine.  Nice colors and nice composition, but I do wonder whether a little more space on the left may have made it better, not sure.</td>', '7 - Good idea.  Criticism; especially for the Challenge, would like to have been able to discern more ''transparency'', ''glass like'' of the ice, but difficult to do I imagine.  Nice colors and nice composition, but I do wonder whether a little more space on the left may have made it better, not sure.', '2005-11-06 07:14:01.000000', NULL, 1),
(1841797, 251020, 39850, '<td valign="top">7 - Like this, and the potential.  Criticism; just would like to be able to see more clarity in the water, ie: the rocks at the bottom, especially for the Challenge.  Composition is nice though, not sure on the heavy and dark frame.</td>', '7 - Like this, and the potential.  Criticism; just would like to be able to see more clarity in the water, ie: the rocks at the bottom, especially for the Challenge.  Composition is nice though, not sure on the heavy and dark frame.', '2005-11-06 07:15:33.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1841801, 251046, 39850, '<td valign="top">5 - Like the concept.  Criticism; a different colored flower (and perhaps different type/shape) would have made this better, doesn''t quite ''fit'' in my opinion.  The shot even without a flower may have even been better, perhaps with water in the vases (apologies if there is, can''t discern it).  The background colors are nice and especially so in the refraction, but again, the flower detracts in this shot for me.</td>', '5 - Like the concept.  Criticism; a different colored flower (and perhaps different type/shape) would have made this better, doesn''t quite ''fit'' in my opinion.  The shot even without a flower may have even been better, perhaps with water in the vases (apologies if there is, can''t discern it).  The background colors are nice and especially so in the refraction, but again, the flower detracts in this shot for me.', '2005-11-06 07:20:14.000000', NULL, 1),
(1841802, 251285, 39850, '<td valign="top">7 - Do like this, unusual and good sharp angle.  Criticism; a slightly ''neater'' crop, choosing beginning/end of certain leaves to begin at the bottom, and possible (not sure) a wider ''framing'' as well, would have made this better in my opinion.  Up to 7 from 6.</td>', '7 - Do like this, unusual and good sharp angle.  Criticism; a slightly ''neater'' crop, choosing beginning/end of certain leaves to begin at the bottom, and possible (not sure) a wider ''framing'' as well, would have made this better in my opinion.  Up to 7 from 6.', '2005-11-06 07:21:41.000000', NULL, 1),
(1841804, 250977, 39850, '<td valign="top">3.  Like the potential.  Criticism; too out of focus in my opinion.  A different (tighter if possible) crop, may have made this better.  Just like to see nice defintion on the duckling, especially it''s feet under the water.</td>', '3.  Like the potential.  Criticism; too out of focus in my opinion.  A different (tighter if possible) crop, may have made this better.  Just like to see nice defintion on the duckling, especially it''s feet under the water.', '2005-11-06 07:23:27.000000', NULL, 1),
