INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1844675, 251387, 44924, '<td valign="top">Wiggis, the mountain in the front sticks a mile straight out of the ground (500m - 2000m). Glaernisch in the back goes from 500m - 3200m, so more than 1.5 miles out of the ground. This picture is breathtaking, but still doesn''t do it any justice being there in person. Glarus, Switzerland, is just an amazing area, and not just cause my mom grew up there. LOL</td>', 'Wiggis, the mountain in the front sticks a mile straight out of the ground (500m - 2000m). Glaernisch in the back goes from 500m - 3200m, so more than 1.5 miles out of the ground. This picture is breathtaking, but still doesn''t do it any justice being there in person. Glarus, Switzerland, is just an amazing area, and not just cause my mom grew up there. LOL', '2005-11-07 12:41:52.000000', NULL, 0),
